+// }
+// };
+exports.check_availability = async (req, res) => {
+  try {
+    const counts = await personalDetails.aggregate([
+      { $match: { iseligible: true } },
+      { $group: { _id: "$bloodgroup", count: { $sum: 1 } } }
+    ]);
+
+    // Format the result to always include all 8 groups, even if count is 0
+    const bloodGroups = ["A-", "A+", "B+", "B-", "AB+", "AB-", "O+", "O-"];
+    const result = {};
+
+    bloodGroups.forEach(group => {
+      const found = counts.find(c => c._id === group);
+      result[group.replace("+", "_pos").replace("-", "_neg")] = found ? found.count : 0;
+    });
+
+    res.status(200).json({
+      message: 'Availability counts retrieved successfully',
+      data: result
+    });
+  } catch (error) {
+    console.error('Error retrieving availability counts:', error);
+    res.status(500).json({ message: 'Error retrieving availability counts' });
+  }
+};
+
+exports.request_status = async (req, res) => {
+  try {
+    const { status } = req.body;
+    const user_id = req.user.id;
+
+    // Validate user
+    const user = await User.findById(user_id);
+    if (!user) {
+      return res.status(404).json({ message: "User not found or unauthorized." });
+    }
+
+    // Validate status value
+    const validStatuses = ['pending', 'fulfilled', 'cancelled'];
+    if (!validStatuses.includes(status)) {
+      return res.status(400).json({ message: "Invalid status value." });
+    }
+
+    // Get the latest request by this user
+    const requestDoc = await request.findOne({ user: user_id }).sort({ createdAt: -1 });
+
+    if (!requestDoc) {
+      return res.status(404).json({ message: "No blood request found for this user." });
+    }
+
+    // Optional: Prevent fulfilling before a donor accepts
+    if (status === 'fulfilled' && !requestDoc.accepted_by) {
+      return res.status(400).json({ message: "Cannot mark as fulfilled before a donor has accepted the request." });
+    }
+
+    // Update status
+    requestDoc.status = status;
+    await requestDoc.save();
+
+    return res.status(200).json({ message: `Request status updated to '${status}'` });
+
+  } catch (error) {
+    console.error("Error updating request status:", error);
+    return res.status(500).json({ message: "Server error while updating request status" });
+  }
+};
+
+exports.acceptRequest = async (req, res) => {
+  try {
+    const donorId = req.user.id;
+    const { token, request_id } = req.body;
+
+    const tokenDoc = await RequestToken.findOne({ token, request_id });
+    if (!tokenDoc || tokenDoc.status !== 'pending') {
+      return res.status(400).json({ message: 'Invalid or already accepted request.' });
+    }
+
+    const requestDoc = await request.findById(request_id);
+    if (!requestDoc) {
+      return res.status(404).json({ message: 'Request not found.' });
+    }
+
+    requestDoc.accepted_by = donorId;
+    tokenDoc.status = 'fulfilled';
+
+    await requestDoc.save();
+    await tokenDoc.save();
+
+    if (requestDoc.accepted_by) {
+  return res.status(400).json({ message: 'Request already accepted by another donor.' });
+}
+
+  const recipientUser = await User.findById(requestDoc.user);
+
+ const uri=`http://localhost:3000/track-donor?donor_id=${donorId}&request_id=${request_id}`
+const recipientMessage = `Good news!
+
+A donor has accepted your blood request for ${requestDoc.blood_type} blood.
+
+📍 Hospital: ${requestDoc.hospital_name}, ${requestDoc.hospital_address}
+📅 Date: ${requestDoc.date.toLocaleDateString()}
+🩸 Units: ${requestDoc.unit_needed}
+To Track the Donor:${uri}
+The donor is now on their way. Our team will keep you updated.
+
+— BloodLink Team`;
+
+if (recipientUser && recipientUser.phone_number) {
+  await sendsms(recipientMessage, [recipientUser.phone_number]);
+}
+    return res.status(200).json({ message: 'You have successfully accepted the request.' });
+  } catch (error) {
+    console.error("Error in acceptRequest:", error);
+    return res.status(500).json({ message: 'Server error during acceptance.' });
+  }
+};
+
+exports.updateDonorLocation = async (req, res) => {
+  try {
+    const donorId = req.user.id;
+    const { lat, lng } = req.body;
+
+    if (!lat || !lng) {
+      return res.status(400).json({ message: "Latitude and longitude are required." });
+    }
+
+    await LiveLocation.findOneAndUpdate( 
+      { donor: donorId },
+      { coordinates: [lng, lat], updatedAt: new Date() },
+      { upsert: true, new: true }
+    );
+
+    return res.status(200).json({ message: "Location updated successfully." });
+
+  } catch (error) {
+    console.error("Error updating donor location:", error);
+    res.status(500).json({ message: "Server error updating location." });
+  }
+};
+
+exports.getDonorLocation = async (req, res) => {
+  try {
+    const { request_id } = req.body;
+
+    const bloodRequest = await request.findById(request_id).populate('accepted_by');
+    if (!bloodRequest || !bloodRequest.accepted_by) {
+      return res.status(404).json({ message: "Donor not yet assigned to this request." });
+    }
+
+    const location = await LiveLocation.findOne({ donor: bloodRequest.accepted_by._id });
+    if (!location) {
+      return res.status(404).json({ message: "No live location available yet." });
+    }
+
+    return res.status(200).json({
+      donor: bloodRequest.accepted_by.name,
+      coordinates: {
+        lat: location.coordinates[1],
+        lng: location.coordinates[0]
+      },
+      updatedAt: location.updatedAt,
+      status: bloodRequest.status
+    });
+
+  } catch (error) {
+    console.error("Error getting donor location:", error);
+    res.status(500).json({ message: "Server error fetching location." });
+  }
+};

