const request = require('../models/request');
const personalDetails = require('../models/persondetail');
const User=require('../models/users');
const feed_back=require('../models/recipient_feedback');
const { sendsms } = require('../utils/sms');
const geocodeAddress = require('../utils/geocode'); // ✅ Make sure this import exists
const crypto = require('crypto');
const RequestToken = require('../models/requestToken');
const LiveLocation = require('../models/livelocation');

exports.bloodrequest = async (req, res) => {
  try {
    const {
      patient_name,
      blood_type,
      unit_needed,
      hospital_name,
      hospital_address,
      date,
      contact_name,
      contact_number
    } = req.body;

    const user_id = req.user.id;
    const user = await User.findById(user_id);
    if (!user) {
      return res.status(404).json({ message: "User not found or unauthorized." });
    }
    //  Save the blood request
    const Requestdetails = new request({
      user: user_id,
      patient_name,
      blood_type,
      unit_needed,
      hospital_name,
      hospital_address,
      date,
      contact_name,
      contact_number
    });

    await Requestdetails.save();
    const token = crypto.randomBytes(16).toString('hex');
await RequestToken.create({
  token,
  request_id:Requestdetails._id
});

    //  Geocode the hospital address
    const hospitalCoords = await geocodeAddress(hospital_address);
    if (!hospitalCoords) {
      return res.status(400).json({ message: "Invalid hospital address — location not found" });
    }

    //  Find eligible donors nearby
    const donors = await personalDetails.find({
      iseligible: true,
      bloodgroup: blood_type.toUpperCase(),
      location: {
        $near: {
          $geometry: {
            type: "Point",
            coordinates: [hospitalCoords.longitude, hospitalCoords.latitude]
          },
          $maxDistance: 5000 // 5 km
        }
      }
    }).populate('user', 'phone_number');

    const phoneNumbers = donors.map(d => d.user.phone_number).filter(Boolean); // Remove undefined/null

    //  Compose message
    const uri=`http://localhost:3000/accept-request?token=${token}&request_id=${Requestdetails._id}`
    const message = `Dear Donor,

We have an urgent requirement for ${blood_type} blood near your location.
A patient at ${hospital_name}, located at ${hospital_address}, needs your help.

🩸 Units Needed: ${unit_needed}
📅 Date Required: ${date}
📞 Contact: ${contact_name}

You are eligible and within 5 km of the hospital.
If you're available, please consider donating — your one donation can save a life!
Accept the request here: ${uri}

Thank you for being a life saver,
— BloodLink Team`;

    //  Send SMS
    if (phoneNumbers.length > 0) {
      await sendsms(message, phoneNumbers);
    }

    res.status(201).json({ message: "Blood request submitted and donors notified successfully" });

  } catch (error) {
    console.error("Error in bloodrequest:", error);
    res.status(500).json({ message: "Server error while submitting blood request" });
  }
};
exports.emergency = async (req, res) => {
  try {
    const user_id = req.user.id;
    const user = await User.findById(user_id);
    if (!user) {
      return res.status(404).json({ message: "User not found or unauthorized." });
    }

    const userRequest = await request.findOne({ user: user_id }).sort({ createdAt: -1 });

    if (!userRequest) {
      return res.status(404).json({ message: "No blood request found for this user." });
    }
    
    request_info=await RequestToken.findOne({request_id:user_id});
   
    if (!request_info || request_info.status !== 'pending') {
  return res.status(400).json({ message: "This blood request has already been fulfilled or doesn't exist." });
}

    const hospitalCoords = await geocodeAddress(userRequest.hospital_address);
    if (!hospitalCoords) {
      return res.status(400).json({ message: "Invalid hospital address — location not found." });
    }

    const donors = await personalDetails.find({
      iseligible: true,
      bloodgroup: userRequest.blood_type.toUpperCase(),
      location: {
        $near: {
          $geometry: {
            type: "Point",
            coordinates: [hospitalCoords.longitude, hospitalCoords.latitude]
          },
          $maxDistance: 5000
        }
      }
    }).populate('user', 'phone_number');

    const phoneNumbers = donors.map(d => d.user.phone_number).filter(Boolean);
    const token=request_info.token;
    const uri=`http://localhost:3000/Accept?token=${token}&request_id=${Requestdetails._id}`
    const message = `🚨 Emergency! 🚨
A patient needs ${userRequest.blood_type} blood near you at ${userRequest.hospital_name}, ${userRequest.hospital_address}.

📅 Date: ${userRequest.date.toLocaleDateString()}
🩸 Units: ${userRequest.unit_needed}
📞 Contact: ${userRequest.contact_name}
  
Accept the request here: ${uri}

You're eligible and within 5 km. Please donate if you can. One donation can save a life.

— BloodLink`;

    const sendIfStillPending = (delayMs, label) => {
      setTimeout(async () => {
        const latestRequest = await request.findById(request_info._id);
        if (latestRequest && latestRequest.status === 'pending') {
          await sendsms(message, phoneNumbers);
          console.log(`Emergency SMS sent again after ${label}`);
        } else {
          console.log(`Request status is '${latestRequest?.status}', skipping SMS for ${label}`);
        }
      }, delayMs);
    };

    if (phoneNumbers.length > 0) {
      await sendsms(message, phoneNumbers);
      console.log("Emergency SMS sent once");

      // Schedule follow-ups
      sendIfStillPending(5 * 60 * 1000, "5 minutes");
      sendIfStillPending(10 * 60 * 1000, "10 minutes");
    } else {
      console.log("No eligible donors found to notify.");
    }

    res.status(201).json({ message: "Emergency donors notified successfully." });

  } catch (error) {
    console.error("Error in emergency request:", error);
    res.status(500).json({ message: "Server error while handling emergency request" });
  }
};

exports.nearbyDonors = async (req, res) => {
  try {
    const { address, blood_type } = req.body;
    if (!blood_type || !address) {
  return res.status(400).json({ message: "Blood type and address are required" });
}

    // Geocode the hospital address
    const hospitalCoords = await geocodeAddress(address);
    if (!hospitalCoords) {
      return res.status(400).json({ message: "Invalid address — location not found" });
    }

    // Find nearby eligible donors
    const donors = await personalDetails.find({
      iseligible: true,
      bloodgroup: blood_type.toUpperCase(),
      location: {
        $near: {
          $geometry: {
            type: "Point",
            coordinates: [hospitalCoords.longitude, hospitalCoords.latitude]
          },
          $maxDistance: 5000 // 5 km
        }
      }
    }).populate('user', 'name phone_number');

    const donorDetails = donors.map(donor => ({
      name: donor.user.name,
      phone: donor.user.phone_number,
      address: donor.address,
    }));

    if (donorDetails.length > 0) {
      return res.status(200).json({ 
        message: "Nearby donors successfully retrieved", 
        data: donorDetails 
      });
    } else {
      return res.status(404).json({ 
        message: "No eligible donors found within 5km radius" 
      });
    }

  } catch (error) {
    console.error("Error in Finding Donors:", error);
    res.status(500).json({ message: "Server error while Finding donors" });
  }
};
exports.recipient_feedback=async (req,res)=>{
  try{
  const {name,rating,feedback}=req.body;
  const user_id = req.user.id;
  const user = await User.findById(user_id);
  if (!user) {
      return res.status(404).json({ message: "User not found or unauthorized." });
   }
  const Feedback=new feed_back({
        user:user_id,
        name,
        rating,
        feedback
    });
    await Feedback.save();
    res.status(201).json({message:'Your feedback has been successfully submitted.'});
  }catch{
    res.status(404).json({message:'Server Error'});
}
};
exports.check_availability = async (req, res) => {
  try {
    const counts = await personalDetails.aggregate([
      { $match: { iseligible: true } },
      { $group: { _id: "$bloodgroup", count: { $sum: 1 } } }
    ]);

    // Format the result to always include all 8 groups, even if count is 0
    const bloodGroups = ["A-", "A+", "B+", "B-", "AB+", "AB-", "O+", "O-"];
    const result = {};

    bloodGroups.forEach(group => {
      const found = counts.find(c => c._id === group);
      result[group.replace("+", "_pos").replace("-", "_neg")] = found ? found.count : 0;
    });

    res.status(200).json({
      message: 'Availability counts retrieved successfully',
      data: result
    });
  } catch (error) {
    console.error('Error retrieving availability counts:', error);
    res.status(500).json({ message: 'Error retrieving availability counts' });
  }
};

exports.request_status = async (req, res) => {
  try {
    const { status } = req.body;
    const user_id = req.user.id;

    // Validate user
    const user = await User.findById(user_id);
    if (!user) {
      return res.status(404).json({ message: "User not found or unauthorized." });
    }

    // Validate status value
    const validStatuses = ['pending', 'fulfilled', 'cancelled'];
    if (!validStatuses.includes(status)) {
      return res.status(400).json({ message: "Invalid status value." });
    }

    // Get the latest request by this user
    const requestDoc = await request.findOne({ user: user_id }).sort({ createdAt: -1 });

    if (!requestDoc) {
      return res.status(404).json({ message: "No blood request found for this user." });
    }

    // Optional: Prevent fulfilling before a donor accepts
    if (status === 'fulfilled' && !requestDoc.accepted_by) {
      return res.status(400).json({ message: "Cannot mark as fulfilled before a donor has accepted the request." });
    }

    // Update status
    requestDoc.status = status;
    await requestDoc.save();

    return res.status(200).json({ message: `Request status updated to '${status}'` });

  } catch (error) {
    console.error("Error updating request status:", error);
    return res.status(500).json({ message: "Server error while updating request status" });
  }
};

