  }
};

exports.updateDonorLocation = async (req, res) => {
  try {
    const donorId = req.user.id;
    const { lat, lng } = req.body;

    if (!lat || !lng) {
      return res.status(400).json({ message: "Latitude and longitude are required." });
    }

    await LiveLocation.findOneAndUpdate( 
      { donor: donorId },
      { coordinates: [lng, lat], updatedAt: new Date() },
      { upsert: true, new: true }
    );

    return res.status(200).json({ message: "Location updated successfully." });

  } catch (error) {
    console.error("Error updating donor location:", error);
    res.status(500).json({ message: "Server error updating location." });
  }
};

exports.getDonorLocation = async (req, res) => {
  try {
    const { request_id } = req.body;

    const bloodRequest = await request.findById(request_id).populate('accepted_by');
    if (!bloodRequest || !bloodRequest.accepted_by) {
      return res.status(404).json({ message: "Donor not yet assigned to this request." });
    }

    const location = await LiveLocation.findOne({ donor: bloodRequest.accepted_by._id });
    if (!location) {
      return res.status(404).json({ message: "No live location available yet." });
    }

    return res.status(200).json({
      donor: bloodRequest.accepted_by.name,
      coordinates: {
        lat: location.coordinates[1],
        lng: location.coordinates[0]
      },
      updatedAt: location.updatedAt,
      status: bloodRequest.status
    });

  } catch (error) {
    console.error("Error getting donor location:", error);
    res.status(500).json({ message: "Server error fetching location." });
  }
};
